const fs = require('fs');
const file = '_worker.js';
let source = fs.readFileSync(file, 'utf8');
const marker = 'bare-login-split-welcome-v1';
if (!source.includes(marker)) {
  source += String.raw`

// bare-login-split-welcome-v1
const bareLoginSplitStyle='<style id="bare-login-split-style">body{background:#f4f4f1!important}.login-wrap{display:grid!important;grid-template-columns:minmax(0,1.05fr) minmax(440px,.95fr)!important;align-content:stretch!important;width:min(1240px,calc(100% - 48px))!important;max-width:none!important;min-height:760px!important;margin:34px auto!important;padding:0!important;background:#fff!important;box-shadow:0 18px 60px rgba(0,0,0,.08)!important}.login-wrap>.member-welcome-banner{grid-column:1!important;grid-row:1!important;width:100%!important;max-width:none!important;min-height:760px!important;height:100%!important;margin:0!important}.login-wrap>.member-welcome-banner img{object-position:center!important}.login-wrap>.member-welcome-banner:after{background:linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.66))!important}.login-wrap>.member-welcome-banner .member-welcome-copy{gap:12px!important;padding:42px!important}.login-wrap>.member-welcome-banner .member-welcome-copy strong{font-size:clamp(58px,6vw,92px)!important}.login-panel{grid-column:2;grid-row:1;display:grid;align-content:center;width:min(520px,calc(100% - 72px));margin:0 auto;padding:58px 0}.login-brand{display:flex;align-items:center;justify-content:space-between;margin-bottom:64px}.login-brand img{width:116px;height:auto;filter:brightness(0)}.login-brand span{font:900 9px/1 InterDisplay,sans-serif;letter-spacing:.16em}.login-form{margin:0!important}.login-field input{height:58px!important;border:0!important;border-bottom:1px solid #bbb!important;border-radius:0!important;padding:0 2px!important;background:transparent!important;font-size:16px!important}.login-field input:focus{border-bottom-color:#111!important;outline:0!important}.member-login{height:58px!important;margin-top:18px!important;border:0!important;border-radius:0!important;background:#111!important;color:#fff!important;font-size:15px!important}.guest-buy{height:52px!important;margin-top:8px!important;border:1px solid #111!important;border-radius:0!important;background:#fff!important;color:#111!important;font-size:14px!important}.login-links{margin:20px 0 40px!important}.divider{margin-bottom:24px!important}.social-row{display:block!important}.social-login.kakao{width:100%!important;max-width:none!important;height:54px!important;border-radius:0!important;background:#fee500!important}.login-panel-note{margin:32px 0 0;padding-top:18px;border-top:1px solid #ddd;color:#777;font:800 10px/1.6 Pretendard,sans-serif}@media(max-width:860px){body{background:#fff!important}.login-wrap{grid-template-columns:1fr!important;width:100%!important;min-height:0!important;margin:0!important;box-shadow:none!important}.login-wrap>.member-welcome-banner{grid-column:1!important;grid-row:1!important;min-height:230px!important;height:230px!important}.login-wrap>.member-welcome-banner .member-welcome-copy{gap:6px!important;padding:22px!important}.login-wrap>.member-welcome-banner .member-welcome-copy small{font-size:8px!important}.login-wrap>.member-welcome-banner .member-welcome-copy strong{font-size:42px!important}.login-wrap>.member-welcome-banner .member-welcome-copy span{font-size:12px!important}.login-wrap>.member-welcome-banner .member-welcome-copy b{min-height:30px!important;font-size:8px!important}.login-panel{grid-column:1;grid-row:2;width:calc(100% - 36px);padding:34px 0 50px}.login-brand{margin-bottom:34px}.login-brand img{width:94px}.login-field input{height:54px!important}.member-login{height:54px!important}.login-links{margin-bottom:32px!important}}</style>';
const bareLoginSplitScript='<script id="bare-login-split-script">(()=>{const main=document.querySelector("main.login-wrap"),banner=main?.querySelector(":scope > .member-welcome-banner");if(!main||!banner||main.querySelector(":scope > .login-panel"))return;const panel=document.createElement("section");panel.className="login-panel";panel.setAttribute("aria-label","베어닷 로그인");panel.innerHTML="<a class=\\"login-brand\\" href=\\"/\\" aria-label=\\"베어닷 홈\\"><img src=\\"'+logoUrl+'\\" alt=\\"BARE.\\"><span>MEMBER LOGIN</span></a>";[...main.children].filter(el=>el!==banner).forEach(el=>panel.appendChild(el));panel.insertAdjacentHTML("beforeend","<p class=\\"login-panel-note\\">신규회원은 회원가입 후 쿠폰함에서<br>첫 구매 10% 할인과 무료배송 쿠폰을 확인할 수 있습니다.</p>");main.insertBefore(banner,main.firstChild);main.appendChild(panel)})();</script>';
const bareLoginSplitBase=simpleLoginPage;
simpleLoginPage=function(){return bareLoginSplitBase().replace('</head>',bareLoginSplitStyle+'</head>').replace('</body>',bareLoginSplitScript+'</body>')};
`;
  fs.writeFileSync(file, source);
}
for (const path of ['.github/redesign-login-split.cjs', '.github/workflows/redesign-login-split.yml']) {
  try { fs.unlinkSync(path); } catch (_) {}
}
